 90     name: "/cost",
 91     description: "Show token usage and cost (/cost stats for summary, /cost detail for breakdown)",
 92     usage: "/cost [stats|detail]",
 93     execute: (arg, ctx) => {
 94       if (costTracker.getUsageSummary()) {
 95         ctx.addStatus(costTracker.formatSummary(CHALK_COLORIZER));
 96         return;
 97       }
 98       if (costTracker.getRequestCount() === 0) {
 99         ctx.addStatus("No API requests yet.");
100         return;
101       }
102       const t = costTracker.getTotalTokens();
103       const cost = costTracker.getEstimatedCost();
104       const requests = costTracker.getRequestCount();
105 
106       if (arg === "stats" || arg === "summary") {
107         ctx.addStatus(costTracker.formatSummary(CHALK_COLORIZER));
108       } else if (arg === "detail" || arg === "usage") {
109         const avgTokensPerReq = Math.round(t.total / requests);
110         const avgCostPerReq = (cost / requests).toFixed(4);
111         const fmt = (n: number) => n.toLocaleString();
112         ctx.addStatus(
113           [
114             "API Usage:",
115             `  Requests:         ${requests}`,
116             `  Total tokens:     ${fmt(t.total)}`,
117             `    Prompt:         ${fmt(t.prompt)}`,
118             `    Completion:     ${fmt(t.completion)}`,
119             `  Estimated cost:   ${cost.toFixed(4)}`,
120             `  Avg tokens/req:   ${fmt(avgTokensPerReq)}`,
121             `  Avg cost/req:     ${avgCostPerReq}`,
122             `  Model:            ${ctx.model}`,
123           ].join("\n"),
124         );
125       } else {
126         ctx.addStatus(
127           `Tokens: ${t.total} (in: ${t.prompt}, out: ${t.completion}) | ` +
128             `Cost: ${cost.toFixed(4)} | Requests: ${requests}`,
129         );
130         ctx.addStatus("Use /cost stats or /cost detail for more info.");
131       }
